from pathlib import Path
import json,math,struct,hashlib,os,datetime
from collections import defaultdict,Counter
P=Path('docs/evidence/appearance-2026-10-05/neutral-head-artist-source'); O=P/'output'
def J(p):return json.loads(p.read_bytes())
def pin(p):
 b=p.read_bytes();return dict(path=p.name,bytes=len(b),sha256=hashlib.sha256(b).hexdigest())
def need(v,w):
 if not v:raise ValueError(w)
def f32(v):return struct.unpack('<f',struct.pack('<f',v))[0]
m=J(O/'mesh.json'); s=J(P/'SOURCE.json'); build=J(O/'BUILD.json'); check=J(O/'CHECK.json');outer=J(P/'OUTER.json'); adm=J(P/'CPU-ADMISSION.json')
for row in adm['bindings']:need(pin(P/row['path'])==row,('admission pin',row['path']))
need(outer['admission_sha256']==pin(P/'CPU-ADMISSION.json')['sha256'] and outer['error'] is None, 'outer admission/error')
need([x['script'] for x in outer['jobs']]==['build.py','check-owned.py'] and all(x['exit_code']==0 and not x.get('timeout') for x in outer['jobs']),'actual jobs')
need(build['pid']==outer['jobs'][0]['pid'] and check['pid']==outer['jobs'][1]['pid'],'PID receipt identities')
need(check['failure'] is None and check['decision']=='A numeric saved-file predicates only','checker refusal')
need(J(P/'check-owned.py.stdout.txt')==check and J(P/'build.py.stdout.txt')['outputs']==build['outputs'],'stdio JSON equality')
need(all((P/(n+'.stderr.txt')).read_bytes()==b'' for n in ['build.py','check-owned.py']),'stderr')
need(outer['started_utc']<=outer['jobs'][0]['started_utc']<=outer['jobs'][0]['collected_utc']<=outer['jobs'][1]['started_utc']<=outer['jobs'][1]['collected_utc']<=outer['collected_utc'],'clock order')
need(outer['collected_utc']<'2026-10-05T21:06:00' and outer['elapsed_seconds']<120,'CPU cutoff/budget')
for row in build['inputs']:need(pin(P/row['path'])==row,('build source',row['path']))
for row in build['outputs']:need(pin(O/row['path'])==row,('build output',row['path']))
for row in check['inputs']:need(pin(O/row['path'])==row,('check input',row['path']))
need(m['source_inputs']==build['inputs'] and m['materials']==s['materials'] and m['material_order']==list(s['materials']),'source/material roles')
need([a['name'] for a in m['parts']]==['Skin','EyeLeft','EyeRight'],'part roles')
need(set(m['feature_owners'])=={'nose_bridge','nose_tip','alar_wings','nostril_recesses','cheeks','chin','brow_ridges','eye_socket_recesses','lip_model','ears','rear','neck'} and set(m['feature_owners'].values())=={'Skin'},'feature ownership')
report=[]; allp=[];alln=[];allf=[];hist=Counter(); reached=Counter()
for a in m['parts']:
 name=a['name'];p=a['positions'];ns=a['normals'];ids=a['ids'];faces=a['triangles'];mats=a['face_materials'];V=len(p)
 need(V==len(ns)==len(ids)==len(set(ids)) and len(faces)==len(mats),'array/ID lengths')
 need(all(len(v)==3 and all(math.isfinite(x) for x in v) for v in p+ns),'finite')
 need(all(.9999<math.fsum(x*x for x in v)<1.0001 for v in ns),'unit normals')
 for field,typ,ext in [('positions','f','f32'),('normals','f','f32'),('triangles','I','u32')]:
  raw=(O/(name+'-'+field+'.'+ext)).read_bytes(); flat=[x for row in a[field] for x in row]
  need(raw==struct.pack('<'+str(len(flat))+typ,*flat),('entire binary',name,field));reached['whole_buffers']+=1
 parent=list(range(V));links=[defaultdict(list) for _ in range(V)];edges=defaultdict(list);seen=set();acc=[[0.,0.,0.] for _ in range(V)];vol=[];minarea=math.inf
 def find(x):
  while parent[x]!=x:parent[x]=parent[parent[x]];x=parent[x]
  return x
 for i,t in enumerate(faces):
  need(len(t)==3 and len(set(t))==3 and all(type(v) is int and 0<=v<V for v in t),('index',name,i))
  key=tuple(sorted(t));need(key not in seen,('duplicate',name,i));seen.add(key)
  x,y,z=[p[v] for v in t];u=[y[k]-x[k] for k in range(3)];v=[z[k]-x[k] for k in range(3)]
  c=[u[1]*v[2]-v[1]*u[2],u[2]*v[0]-v[2]*u[0],u[0]*v[1]-v[0]*u[1]]
  area=math.sqrt(sum(w*w for w in c));need(math.isfinite(area) and area>1e-12,('area',name,i));minarea=min(minarea,area)
  vol.append(math.fsum(x[k]*c[k] for k in range(3))/6)
  for vert in t:
   for k in range(3):acc[vert][k]+=c[k]
  for q in range(3):
   aa,bb,cc=t[q],t[(q+1)%3],t[(q+2)%3];edges[min(aa,bb),max(aa,bb)].append((aa,bb));links[aa][bb].append(cc);links[aa][cc].append(bb);parent[find(bb)]=find(aa)
  material=m['material_order'][mats[i]];hist[name+'/'+material]+=1
  if name=='Skin':
   if any(ids[v].startswith('cup:') for v in t): expected='Skin'
   else:
    x,y,z=[sum(p[v][k] for v in t)/3 for k in range(3)]
    brow=z>0 and abs(abs(x)-.225)<.15 and abs(y-(.405-.055*((abs(x)-.225)/.15)**2))<.014
    lip=z>0 and (x/.18)**2+((y+.275)/.054)**2<1
    expected='Brow' if brow else 'Lips' if lip else 'Skin'
  else:
   angles=[0 if ids[v]=='front-pole' else math.pi if ids[v]=='rear-pole' else math.pi*int(ids[v].split(':')[1])/s['eyes']['companion']['polar_steps'] for v in t]
   theta=sum(angles)/3;cut=s['eyes']['companion']['material_theta_cutoffs_radians'];expected='Pupil' if theta<=cut['pupil'] else 'Iris' if theta<=cut['iris'] else 'Sclera'
  need(material==expected,('material duty',name,i,material,expected));reached['face_materials']+=1
 need(all(len(e)==2 and e[0]==e[1][::-1] for e in edges.values()),('closed opposed',name))
 need(len({find(i) for i in range(V)})==1 and V-len(edges)+len(faces)==2,('component/euler',name))
 for i,link in enumerate(links):
  need(link and all(len(v)==2 and len(set(v))==2 for v in link.values()),('link degree',name,i))
  todo=[next(iter(link))];visited=set()
  while todo:
   v=todo.pop()
   if v not in visited:visited.add(v);todo.extend(link[v])
  need(len(visited)==len(link),('link cycle',name,i))
  length=math.sqrt(sum(x*x for x in acc[i]));need(length>0 and [f32(x/length) for x in acc[i]]==ns[i],('normal byte owner',name,i));reached['vertices_normal_link']+=1
 if name=='Skin':
  expected={'bottom-pole','top-pole'}
  for j in range(s['grid']['height_steps']):
   for u in range(s['grid']['azimuth_steps']):
    if not any(q['u_min']<u<q['u_max'] and q['j_min']<j<q['j_max'] for q in s['eyes']['patches']):expected.add('grid:'+str(j)+':'+str(u))
  need(set(a['rims'])=={'left','right'},'rim roles')
  for q in s['eyes']['patches']:
   lo,hi,j0,j1=q['u_min'],q['u_max'],q['j_min'],q['j_max']; r=a['rims'][q['name']]
   perimeter=[(j0,u) for u in range(lo,hi)]+[(j,hi) for j in range(j0,j1)]+[(j1,u) for u in range(hi,lo,-1)]+[(j,lo) for j in range(j1,j0,-1)]
   wanted=['grid:'+str(j)+':'+str(u) for j,u in perimeter]
   need([ids[v] for v in r['rim']]==r['source_grid_ids']==wanted,('shared rim order',q['name']))
   back=['cup:'+q['name']+':'+str(i) for i in range(40)];centre='cup:'+q['name']+':centre';need([ids[v] for v in r['back']]==back and ids[r['centre']]==centre,'cup IDs');expected.update(back+[centre])
   cycles={min(tuple(t),tuple(t[1:]+t[:1]),tuple(t[2:]+t[:2])) for t in faces}
   for k in range(40):
    n=(k+1)%40
    for t in [[r['rim'][k],r['rim'][n],r['back'][n]],[r['rim'][k],r['back'][n],r['back'][k]],[r['back'][k],r['back'][n],r['centre']]]:need(min(tuple(t),tuple(t[1:]+t[:1]),tuple(t[2:]+t[:2])) in cycles,'oriented cup face')
 else:expected={'front-pole','rear-pole'}|{'eye:'+str(j)+':'+str(u) for j in range(1,s['eyes']['companion']['polar_steps']) for u in range(s['eyes']['companion']['azimuth_steps'])};need(a['rims']=={},'eye rim roles')
 need(set(ids)==expected,('complete source IDs',name))
 volume=math.fsum(vol);need(volume>0 and math.isfinite(volume),('volume sign',name))
 report.append(dict(part=name,vertices=V,faces=len(faces),edges=len(edges),components=1,euler=2,minimum_double_area=minarea,signed_volume_fsum=volume,stored_volume=next(z['signed_volume'] for z in check['parts'] if z['part']==name)))
 offset=len(allp);allp+=p;alln+=ns;allf += [(name,m['material_order'][mat],tuple(v+offset for v in t)) for t,mat in zip(faces,mats)]
# Stream the complete original OBJ, restoring the prescribed float32 identities.
vi=ni=fi=0;group=material=None;objects=[]
for line in (O/'neutral-head.obj').read_text().splitlines():
 words=line.split();tag=words[0]
 if tag=='v':need([f32(float(x)) for x in words[1:]]==allp[vi],('OBJ vertex',vi));vi+=1
 elif tag=='vn':need([f32(float(x)) for x in words[1:]]==alln[ni],('OBJ normal',ni));ni+=1
 elif tag=='f':
  pairs=[x.split('//') for x in words[1:]];need(all(int(x)==int(y) for x,y in pairs),'OBJ normal indexing');need((group,material,tuple(int(x)-1 for x,y in pairs))==allf[fi],('OBJ face',fi));fi+=1
 elif tag=='g':group=words[1]
 elif tag=='o':objects.append(words[1])
 elif tag=='usemtl':material=words[1]
 elif tag=='mtllib':need(words==['mtllib','neutral-head.mtl'],'MTL role')
 else:raise ValueError(('unknown OBJ',tag))
need((vi,ni,fi)==(len(allp),len(alln),len(allf)) and objects==['Skin','EyeLeft','EyeRight'],'OBJ whole counts')
mtl={};name=None
for line in (O/'neutral-head.mtl').read_text().splitlines():
 w=line.split()
 if w[0]=='newmtl':name=w[1];need(name not in mtl,'duplicate material');mtl[name]={}
 else:need(w[0] not in mtl[name],'duplicate MTL key');mtl[name][w[0]]=[float(x) for x in w[1:]]
need(set(mtl)==set(s['materials']),'MTL all six')
for name,item in s['materials'].items():need(mtl[name]=={'Kd':[int(item['colour'][j:j+2],16)/255 for j in (1,3,5)],'d':[1.],'Pr':[item['roughness']]},('MTL value',name))
need({key.split('/')[1] for key in hist}==set(m['material_order']),'six materials reached')
print(json.dumps(dict(decision='A independently observed saved-data predicates only',pid=os.getpid(),collected_utc=datetime.datetime.now(datetime.timezone.utc).isoformat(),parts=report,total_vertices=len(allp),total_faces=len(allf),material_counts=dict(hist),reached=dict(reached),obj_counts=[vi,ni,fi],byte_buffers=9,whole_source_ids=True,oriented_shared_cups=240,job_pids=[x['pid'] for x in outer['jobs']],outer_collected=outer['collected_utc'],limits='No independent analytic coordinate oracle, self-intersection, geometric embedding, skin-eye containment, anatomy, fit, rig, motion, appearance, GPU or future native acceptance.')))
